import React from "react";

import { Link, useLocation } from 'react-router-dom';
//imagenes
import logoG from '../assets/Logo_GO.jpeg'; 
import "./../Sidebar_p-a.css";

export default function Sidebar() {
    return(
        <aside className="sidebar">
            <div className="logo">
                <a href="/panel_control.jsx">
                    <img src={logoG} alt="Logo GuramaOnline" />
                </a>
            </div>

            <nav className="menu">
                <a href="/panel_control.jsx" className="menu-item activo">
                    <i className="fa-solid fa-gauge" />
                    <span>Panel de control</span>
                </a>

                <a href="/productos"> 
                {/*conectar con la vista de productos*/}
                    <i className="fa-solid fa-box" />
                    <span>Productos</span>
                </a>

                <a href="/movimientos">  {/*conectar con la vista de movimientos*/}
                    <i className="fa-solid fa-arrow-right-arrow-left" />
                    <span>Movimientos</span>
                </a>

                <a href="/usuarios">  {/*conectar con la vista de usuarios*/}
                    <i className="fa-solid fe-user" />
                    <span>Usuarios</span>
                </a>

                <a href="/pedidos_realizados">  {/*es la misma vista de barra_pricipal solo que le cambiamos el nombre del archivo*/}
                    <i className="fa-solid fa-user-cog" />
                    <span>Pedidos realizados</span>
                </a>
            </nav>
        </aside>
    );
}
